head.script:
// 원본 : ULDFIL52110 법인명 찾기 팝업화면 (/ui/lst/lstinvstg/ULDFIL52110.xml)


///////// 1. 변수 및 선언 영역 /////////

scwin.pageIndex = 1;
scwin.pageSize = 15;
scwin.pageItemCnt = 10;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 14
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function() {
	await scwin.search();

	// 통신 전 : paging 설정
	scwin.setPagingInfo();
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name scwin.grd_list_oncellclick
 * @author Inswave
 * @date 2026. 08. 14
 * @description 그리드뷰 oncellclick 이벤트ist_oncellclick
 *  * @author Inswave
  * @date 2026. 08. 14
   * @description 그리드뷰 oncellclick 이벤트
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_list_oncellclick = function (rowIndex, columnIndex, columnId) {
    const data = {
        isurCd: dlt_selectRes.getCellData(rowIndex, "isurCd"),
        comNm: dlt_selectRes.getCellData(rowIndex, "comNm"),
        bzProcsNo: dlt_selectRes.getCellData(rowIndex, "bzProcsNo"),
    };
    $c.win.closePopup(data);
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 08. 14
 * @description 목록 조회
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function() {
    dma_selectReq.set("userId", $c.session.getUserInfo("integUsrId")); //로그인사용자ID
    dma_selectReq.set("page", scwin.pageIndex); //현재 페이지 번호
    dma_selectReq.set("size", scwin.pageSize); //페이지당 데이터 개수

    const sbmOptions = {
        id : "sbm_select",
        method: "get",
        action : "/api/listing/listinvstg/prtdepo-disposal/corpration/select-list-paging",
        ref : "dma_selectReq",
        target : "dlt_selectRes=body.content",
        gridview : "grd_list",
        isProcessMsg : false 
    };

    const result = await $c.sbm.executeDynamic(sbmOptions);

	// 통신 후 : paging 설정
	scwin.setPagingInfo(result);
};

/**
 * @method
 * @name scwin.setPagingInfo
 * @author chunga
 * @date 2026. 07. 30
 * @description Paging 컴포넌트 설정
 * @param 
 * @returns
 * @hidden N
*/
scwin.setPagingInfo = function (result = {}) {
	const pagingInfo = {
		pageType: "P",                 		// S/P/A Default=P
		rowNumVisble: "grd_list",			// gridView에 rowNumVisible 값 설정
		maxRowNum: 15,			  			// gridView에 최대 visibleRowNum 값 설정
		pageListId: "pglList",         		// 페이지 리스트 아이디
		pageFunction: "scwin.search",  		// 페이징 처리 함수
		currentPage: scwin.pageIndex,       // 현재 페이지
		totalCountId: "tbx_totCnt",     	// total count 출력 아이디
		pageSize: scwin.pageItemCnt			// 페이징 시 출력해줄 페이지 번호 개수
	};

	// 통신 전: 기본값 병합 + DataMap 컬럼 설정
	$c.sbm.setPagingInfo(pagingInfo, "dmaPaging", result.responseJSON?.body?.totalCount || 0);
};


///////// 5. 일반/업무 함수 영역 /////////
